                float2 sv = uv*amzp_scale+i*134.53-M;
                col += StarLayer(sv, t, fade)*fade;
            }
            if( (amzp_BURST>0.5) ) {
            float burstFade = smoothstep(0.0, 0.02, abs(burst));
            float amzLocal_size = 0.9*sin(t)+1.0;
            amzLocal_size = max(amzLocal_size, sqrt(amzLocal_size));
            float fade = amzLocal_size/d;
            col *= mix(1.0, fade, burstFade);
            col += fade*0.2*float3(amzp_COLB.rgb)*bla*burstFade;
            t*=1.5;
            a -= M.x*0.1;
            float rays = sin(a*5.0+t*3.0)-cos(a*7.0-t);
            rays *= sin(a+t+sin(a*4.0)*10.0)*0.5+0.5;
            col += rays*bla*0.1*burstFade;
            col += 1.0-burstFade; }
            else {
            col *= 4.0; }
            fragColor = float4(col,1.0);
     float4 factor = mix(texColorX,fragColor,1.0);
        float4 resultfinal;
          if( int(amzp_blendMode)==0 ) {
            resultfinal = (factor * amzp_hardness) * texColor.a; }
          else if( int(amzp_blendMode)==1 ) { factor *= amzp_hardness;
            float4 c = factor + float4(1.0)*(1.0-factor.a);
            resultfinal = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
          else if( int(amzp_blendMode)==2 ) { factor *= amzp_hardness;
            resultfinal = float4( 1.0-((1.0-(texColor.rgb/texColor.a))*(1.0-factor.rgb)),1.0) * texColor.a; }
          else if( int(amzp_blendMode)==3 ) { factor *= amzp_hardness;
            resultfinal = (newLayer(texColor, factor) * amzp_hardness) * texColor.a; }
     amzOutput = mix(texColor, resultfinal, amzp_alpha) * texColor.a;
        }

